// Wat word jij? · Mariene biologie 2 · Zuurder water — eigen tekenfuncties (7 nov 2026). Voorvoegsel mb2_.
// Seriekleuren: teal = zeewater, oker = kalk en schelp, paars = CO₂ en H⁺ (alleen die), koraal = let op, goud = focus en de stempel.
// Maten: personen 430 px ≈ 1,65 m → 2,6 px per cm. Oesterlarve ± 0,1 mm: alleen in een zoomcirkel of onder de microscoop.

// =====================================================================
// 0. ALGEMENE HULPJES (zoals Milieukunde 2, teken_mk2.js §6; hier zelf gedefinieerd omdat engine/scenes.js r.33+ niet meegaat)
// =====================================================================
const GROND = 860;
const MB2_PX_CM = 2.6;
function antwoord(ctx, s2, a = 1) { regel(ctx, s2, 120, 150, a, C.groen, 40, 'left', 700); }
function metaA(ctx, s2, x, y, a, col = C.grain, al = 'left', px = 28) { if (a <= 0.01) return; ctx.save(); ctx.globalAlpha *= a; mb2_meta(ctx, s2, x, y, col, al, px); ctx.restore(); }
function fase(t, t0, t1, d = 0.5) { return ramp(t, t0, d) * (1 - ramp(t, t1 - d, d)); }
function laag(ctx, a, fn) { if (a <= 0.01) return; ctx.save(); ctx.globalAlpha *= a; fn(); ctx.restore(); }
function lijn(ctx, pts, col, lw = 3, a = 1) { if (a <= 0.01) return; ctx.save(); ctx.globalAlpha *= a; ctx.strokeStyle = col; ctx.lineWidth = lw; ctx.lineCap = 'round'; ctx.lineJoin = 'round'; ctx.beginPath(); pts.forEach((p, i) => i ? ctx.lineTo(p[0], p[1]) : ctx.moveTo(p[0], p[1])); ctx.stroke(); ctx.restore(); }
function stippel(ctx, x0, y0, x1, y1, col, a = 1, lw = 3) { if (a <= 0.01) return; ctx.save(); ctx.globalAlpha *= a; ctx.setLineDash([12, 9]); ctx.strokeStyle = col; ctx.lineWidth = lw; ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(x1, y1); ctx.stroke(); ctx.restore(); }
function kaart(ctx, x, y, w, h, a = 1, rand = C.line) { if (a <= 0.01) return; ctx.save(); ctx.globalAlpha *= a; roundRect(ctx, x, y, w, h, 16); shape(ctx, rgba('#0D1420', 0.9), rgba(rand, 0.85), 2); ctx.restore(); }
function filmKaartje(ctx, x, y, s2, a = 1) { if (a <= 0.01) return; ctx.save(); ctx.globalAlpha *= a; ctx.font = fTekst(36, 700); const ww = ctx.measureText(s2).width + 100; roundRect(ctx, x, y, ww, 72, 12); shape(ctx, rgba('#0D1420', 0.85), rgba(C.line, 0.6), 2);
  ctx.beginPath(); ctx.moveTo(x + 26, y + 22); ctx.lineTo(x + 52, y + 36); ctx.lineTo(x + 26, y + 50); ctx.closePath(); ctx.fillStyle = C.goud; ctx.fill(); text(ctx, s2, x + 66, y + 49, fTekst(36, 700), C.text, 'left'); ctx.restore(); }
function somRegel(ctx, s2, x, y, a = 1, kl = C.text, px = 48, al = 'left') { if (a <= 0.01) return; ctx.save(); ctx.globalAlpha *= a; text(ctx, s2, x, y, fTekst(px, 800), kl, al); ctx.restore(); }
// harde wissel rond een tijdstip: eerst het oude weg, dan het nieuwe (geen twee lagen over elkaar, geen spookachtige mensen)
function wisselT(t, t0, d = 0.3) { return [1 - ramp(t, t0 - d - 0.05, d), ramp(t, t0, d)]; }
// kleurtokens van deze film
const MB2 = { blad: '#22304A', bladR: '#5A6A88', map: '#B8924E', mapD: '#8E6E36', geel: '#F2D86A', geelD: '#C9A83A', inkt: '#2A2414',
  water: '#2E6E8E', waterD: '#1B4562', diep: '#163A55', schelp: '#D9CDB4', schelpD: '#9C8B6A', schelpP: '#8A6A8E', kalk: '#C9A35C', calcium: '#DCE3EC',
  mossel: '#2C3448', mosselL: '#4A5878', glas: '#AFC0D0' };


// Meta-tekst voor deze film (review 7 nov 2026): hoofdletters, maar 'pH' blijft 'pH', µ blijft µ, en nooit kleiner dan 28 px
function _mb2Hoofd(s) { return s.toUpperCase().replace(/\u039C(?:([MGS])(?![A-Z]))?/g,(a,u)=>'\u00B5'+(u?u.toLowerCase():'')).replace(/Μ(?:([MGS])(?![A-Z]))?/g, (a, u) => 'µ' + (u ? u.toLowerCase() : '')).replace(/(^|[^A-Z])PH(?=[^A-Z]|$)/g, '$1pH').replace(/(\d) MM\b/g, '$1 mm'); }
function mb2_meta(ctx, s, x, y, color = C.grain, align = 'left', px = 28) { ctx.save(); ctx.font = fMeta(Math.max(28, px)); ctx.fillStyle = color; ctx.textAlign = align; ctx.textBaseline = 'alphabetic'; ctx.letterSpacing = '3px'; ctx.fillText(_mb2Hoofd(s), x, y); ctx.restore(); }
// naam + metaregel (28 px) direct bij een onderdeel, donkere rand, geen wijslijn (zoals naamBij, met de pH-regel)
function mb2_naam(ctx, name, meta, x, y, alpha = 1, align = 'left', color = C.text) { if (alpha <= 0.01) return; ctx.save(); ctx.globalAlpha *= alpha; ctx.textBaseline = 'alphabetic'; ctx.lineJoin = 'round';
  const regels = [[name, fTekst(36, 600), color, 0, '0px']]; if (meta) regels.push([_mb2Hoofd(meta), fMeta(28), C.grain, 32, '3px']);
  const maat = regels.map(([s, f, , , ls]) => { ctx.font = f; ctx.letterSpacing = ls; return ctx.measureText(s).width; }); const w = Math.max(...maat);
  let bx = align === 'left' ? x : (align === 'right' ? x - w : x - w / 2); bx = Math.max(24, Math.min(W - 24 - w, bx));
  regels.forEach(([s, f, col, dy, ls], i) => { if (!s) return; ctx.font = f; ctx.letterSpacing = ls; ctx.textAlign = 'left'; const lx = align === 'left' ? bx : (align === 'right' ? bx + w - maat[i] : bx + (w - maat[i]) / 2); ctx.strokeStyle = rgba(C.bgMicro, 0.85); ctx.lineWidth = 7; ctx.strokeText(s, lx, y + dy); ctx.fillStyle = col; ctx.fillText(s, lx, y + dy); });
  ctx.letterSpacing = '0px'; ctx.restore(); }
function mb2_zoom(ctx, x, y, r, sx, sy, caption, a, fn) { zoomCircle(ctx, x, y, r, sx, sy, '', a, fn); if (caption && a > 0.01) { ctx.save(); ctx.globalAlpha *= a; mb2_meta(ctx, caption, x, y + r + 40, C.grain, 'center', 28); ctx.restore(); } }
// meta in een donkere pil (Part C C5) voor tekst op het decor
function mb2_pil(ctx, s, x, y, a = 1, col = C.grain, align = 'center', px = 28) { if (a <= 0.01) return; ctx.save(); ctx.globalAlpha *= a; ctx.font = fMeta(px); ctx.letterSpacing = '3px'; const w = ctx.measureText(_mb2Hoofd(s)).width + 32; ctx.letterSpacing = '0px'; const x0 = align === 'center' ? x - w / 2 : align === 'right' ? x - w : x - 16;
  roundRect(ctx, x0, y - px - 8, w, px + 22, 8); ctx.fillStyle = rgba('#121A26', 0.85); ctx.fill(); mb2_meta(ctx, s, x0 + 16, y, col, 'left', px); ctx.restore(); }
function mb2_tekstPil(ctx, s, x, y, a = 1, col = C.groen, px = 40) { if (a <= 0.01) return; ctx.save(); ctx.globalAlpha *= a; ctx.font = fTekst(px, 700); const w = ctx.measureText(s).width + 36; roundRect(ctx, x - 18, y - px - 8, w, px + 24, 8); ctx.fillStyle = rgba('#121A26', 0.85); ctx.fill(); text(ctx, s, x, y, fTekst(px, 700), col, 'left'); ctx.restore(); }

// =====================================================================
// 1. MOLECULEN (Micro, alleen in een zoomcirkel of op een blad): CO₂ en H⁺ paars, water teal, carbonaat oker, calcium licht
// =====================================================================
function _bol(ctx, x, y, r, fill, stroke, lw = 1.5) { ctx.beginPath(); ctx.arc(x, y, Math.max(0.1, r), 0, 6.283); ctx.fillStyle = fill; ctx.fill(); if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); } }
// CO₂: O=C=O op een rij (lineair), r = straal van het C-atoom
function mb2_co2(ctx, x, y, r = 14, o = {}) { const { a = 1, rot = 0, lab = false } = o; if (a <= 0.01) return; ctx.save(); ctx.globalAlpha *= a; ctx.translate(x, y); ctx.rotate(rot);
  const ro = r * 0.92, d = r * 1.45; ctx.strokeStyle = lighten(C.paars, 0.3); ctx.lineWidth = r * 0.28; ctx.beginPath(); ctx.moveTo(-d, 0); ctx.lineTo(d, 0); ctx.stroke();
  _bol(ctx, -d, 0, ro, '#A99AD6', lighten('#A99AD6', 0.3)); _bol(ctx, d, 0, ro, '#A99AD6', lighten('#A99AD6', 0.3)); _bol(ctx, 0, 0, r, C.paars, lighten(C.paars, 0.35));
  ctx.restore(); if (lab) mb2_naam(ctx, 'CO₂', '', x, y + r * 2.6, a, 'center'); }
// H₂O: V-vorm, teal
function mb2_h2o(ctx, x, y, r = 14, o = {}) { const { a = 1, rot = 0 } = o; if (a <= 0.01) return; ctx.save(); ctx.globalAlpha *= a; ctx.translate(x, y); ctx.rotate(rot);
  const hx = r * 1.15, hy = r * 0.9; _bol(ctx, -hx, hy, r * 0.55, '#CFE3EE', '#F2F8FC'); _bol(ctx, hx, hy, r * 0.55, '#CFE3EE', '#F2F8FC'); _bol(ctx, 0, 0, r, C.teal, lighten(C.teal, 0.35)); ctx.restore(); }
// H⁺: klein paars bolletje met een plus
function mb2_hplus(ctx, x, y, r = 11, o = {}) { const { a = 1, ring = 0 } = o; if (a <= 0.01) return; ctx.save(); ctx.globalAlpha *= a; _bol(ctx, x, y, r, '#B3A6E0', lighten('#B3A6E0', 0.35), 1.5);
  ctx.strokeStyle = '#2A2050'; ctx.lineWidth = Math.max(1.5, r * 0.22); ctx.lineCap = 'round'; ctx.beginPath(); ctx.moveTo(x - r * 0.45, y); ctx.lineTo(x + r * 0.45, y); ctx.moveTo(x, y - r * 0.45); ctx.lineTo(x, y + r * 0.45); ctx.stroke();
  if (ring > 0.01) { ctx.globalAlpha *= ring; ctx.strokeStyle = C.goud; ctx.lineWidth = 3; ctx.beginPath(); ctx.arc(x, y, r + 6, 0, 6.283); ctx.stroke(); } ctx.restore(); }
// carbonaat CO₃²⁻: C in het midden, drie O in een driehoek, oker; o.h = 0..1 een H⁺ zit vast (bicarbonaat)
function mb2_carbonaat(ctx, x, y, r = 13, o = {}) { const { a = 1, rot = 0, h = 0, ring = 0 } = o; if (a <= 0.01) return; ctx.save(); ctx.globalAlpha *= a; ctx.translate(x, y); ctx.rotate(rot);
  const d = r * 1.5; ctx.strokeStyle = lighten(C.oker, 0.25); ctx.lineWidth = r * 0.26; for (let k = 0; k < 3; k++) { const an = -Math.PI / 2 + k * 2.094; ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(Math.cos(an) * d, Math.sin(an) * d); ctx.stroke(); }
  for (let k = 0; k < 3; k++) { const an = -Math.PI / 2 + k * 2.094; _bol(ctx, Math.cos(an) * d, Math.sin(an) * d, r * 0.85, '#E2C58A', lighten('#E2C58A', 0.3)); }
  _bol(ctx, 0, 0, r, C.oker, lighten(C.oker, 0.35));
  if (h > 0.01) { const an = -Math.PI / 2, hx = Math.cos(an) * d, hy = Math.sin(an) * d - r * 0.85 - r * 0.55 * ease(h) + r * 1.4 * (1 - ease(h)) * 0; ctx.save(); ctx.globalAlpha *= clamp(h * 2, 0, 1); ctx.rotate(-rot); const R = Math.hypot(hx, hy), A = Math.atan2(hy, hx) + rot; mb2_hplus(ctx, Math.cos(A) * R, Math.sin(A) * R, r * 0.7); ctx.restore(); }
  if (ring > 0.01) { ctx.globalAlpha *= ring; ctx.strokeStyle = C.goud; ctx.lineWidth = 3; ctx.beginPath(); ctx.arc(0, 0, d + r * 1.1, 0, 6.283); ctx.stroke(); }
  ctx.restore(); }
// calcium Ca²⁺: lichte bol (iets groter dan een O)
function mb2_calcium(ctx, x, y, r = 15, o = {}) { const { a = 1 } = o; if (a <= 0.01) return; ctx.save(); ctx.globalAlpha *= a; _bol(ctx, x, y, r, MB2.calcium, '#FFFFFF', 1.5);
  text(ctx, 'Ca', x, y + r * 0.36, fTekst(Math.max(12, r * 0.95), 700), '#3A4458', 'center'); ctx.restore(); }
// koolzuur H₂CO₃: carbonaat met één H⁺ vast (boven) en één H⁺ die loslaat (los 0..1 → drijft naar rechtsonder)
function mb2_koolzuur(ctx, x, y, r = 13, o = {}) { const { a = 1, los = 0 } = o; if (a <= 0.01) return; ctx.save(); ctx.globalAlpha *= a;
  mb2_carbonaat(ctx, x, y, r, { h: 1 }); const an = -Math.PI / 2 + 2.094, d = r * 1.5 + r * 1.35 + ease(los) * r * 3.4; mb2_hplus(ctx, x + Math.cos(an) * d, y + Math.sin(an) * d, r * 0.7, { ring: los > 0.5 ? (los - 0.5) * 2 : 0 }); ctx.restore(); }

// kalkblokjes (calciumcarbonaat) als kristalrand: n = aantal blokjes dat al vastzit
function mb2_kalkrand(ctx, x, y, w, n, o = {}) { const { a = 1, bs = 34, rijen = 3, gat = [] } = o; if (a <= 0.01) return; ctx.save(); ctx.globalAlpha *= a; const per = Math.floor(w / bs); let k = 0;
  for (let r = 0; r < rijen; r++) for (let i = 0; i < per; i++) { const vol = clamp(n - k, 0, 1); k++; if (vol <= 0.01 || gat.includes(k - 1)) continue; const bx = x + i * bs + (r % 2) * bs * 0.5, by = y - (r + 1) * bs * 0.82;
    ctx.save(); ctx.globalAlpha *= vol; roundRect(ctx, bx + 2, by + 2, bs - 4, bs * 0.82 - 4, 4); shape(ctx, r === rijen - 1 ? '#D8B676' : MB2.kalk, lighten(MB2.kalk, 0.35), 1.2); ctx.restore(); }
  ctx.restore(); }

// =====================================================================
// 2. SCHELPDIEREN
// =====================================================================
// Japanse oester (Crassostrea / Magallana gigas), bovenaanzicht van de bolle klep: langwerpig, onregelmatig, slot (umbo) smal boven,
// brede golvende rand onder met lamellen (groeiranden), vuilwit met paarse strepen. Lengte ± 8–20 cm. s = 1 → 160 px lang.
function mb2_oester(ctx, x, y, s = 1, o = {}) { const { a = 1, rot = 0, rand = 0, licht = 0 } = o; if (a <= 0.01) return; ctx.save(); ctx.globalAlpha *= a; ctx.translate(x, y); ctx.rotate(rot); ctx.scale(s, s);
  const omtrek = (k) => { ctx.beginPath(); ctx.moveTo(0, -80 * k); ctx.bezierCurveTo(22 * k, -78 * k, 30 * k, -40 * k, 44 * k, -10 * k);
    for (let i = 0; i <= 10; i++) { const u = i / 10, an = -0.15 + u * 3.44, rr = (52 + Math.sin(i * 2.7) * 5) * k; ctx.lineTo(Math.cos(an) * rr * 0.98, 18 * k + Math.sin(an) * rr * 1.18); }
    ctx.bezierCurveTo(-46 * k, -6 * k, -28 * k, -48 * k, -12 * k, -74 * k); ctx.closePath(); };
  omtrek(1); ctx.fillStyle = MB2.schelp; ctx.fill(); ctx.strokeStyle = MB2.schelpD; ctx.lineWidth = 2.5; ctx.stroke();
  ctx.save(); omtrek(1); ctx.clip(); // paarse strepen vanaf het slot, groeiranden (lamellen) als golvende lijnen
  ctx.strokeStyle = rgba(MB2.schelpP, 0.55); ctx.lineWidth = 5; [-0.5, -0.2, 0.15, 0.45].forEach(an => { ctx.beginPath(); ctx.moveTo(0, -70); ctx.quadraticCurveTo(Math.sin(an) * 50, 0, Math.sin(an) * 80, 90); ctx.stroke(); });
  ctx.strokeStyle = rgba('#7E6E52', 0.8); ctx.lineWidth = 2; for (let k = 0.62; k <= 0.95; k += 0.11) { ctx.save(); ctx.translate(0, -60 * (1 - k)); omtrek(k); ctx.stroke(); ctx.restore(); }
  ctx.restore();
  if (rand > 0.01) { ctx.save(); ctx.globalAlpha *= rand; omtrek(1); ctx.strokeStyle = C.goud; ctx.lineWidth = 5; ctx.setLineDash([]); ctx.stroke(); ctx.restore(); }
  ctx.restore(); }
// gewone mossel (Mytilus edulis), zijaanzicht van één klep: wigvorm met spitse top (umbo) links, blauwzwart, groeilijnen. s = 1 → 150 px lang (± 6 cm in een zoom)
function mb2_mossel(ctx, x, y, s = 1, o = {}) { const { a = 1, rot = 0 } = o; if (a <= 0.01) return; ctx.save(); ctx.globalAlpha *= a; ctx.translate(x, y); ctx.rotate(rot); ctx.scale(s, s);
  const vorm = (k) => { ctx.beginPath(); ctx.moveTo(-75 * k, 8 * k); ctx.bezierCurveTo(-60 * k, -20 * k, -10 * k, -40 * k, 40 * k, -36 * k); ctx.bezierCurveTo(78 * k, -32 * k, 84 * k, 10 * k, 66 * k, 24 * k); ctx.bezierCurveTo(30 * k, 40 * k, -40 * k, 30 * k, -75 * k, 8 * k); ctx.closePath(); };
  vorm(1); ctx.fillStyle = MB2.mossel; ctx.fill(); ctx.strokeStyle = MB2.mosselL; ctx.lineWidth = 2.5; ctx.stroke();
  ctx.save(); vorm(1); ctx.clip(); ctx.strokeStyle = rgba('#6A7AA0', 0.55); ctx.lineWidth = 1.8; for (let k = 0.4; k < 1; k += 0.14) { ctx.save(); ctx.translate(-75 * (1 - k), 8 * (1 - k)); vorm(k); ctx.stroke(); ctx.restore(); }
  ctx.fillStyle = rgba('#7A8AB8', 0.25); ctx.beginPath(); ctx.ellipse(10, -18, 40, 8, -0.1, 0, 6.283); ctx.fill(); ctx.restore(); ctx.restore(); }
// oesterlarve ± 0,1 mm (alleen in een zoomcirkel): u = 0 trochofoor (rond, trilhaarband), u = 1 D-larve (rechte slotlijn boven,
// ronde rand onder, twee kleppen, velum met trilhaartjes). o.mis = 0..1 misvormd (gedeukte slotlijn, schelp niet af).
// o.grijs = dood/niet ontwikkeld. r = halve breedte in px.
function mb2_larve(ctx, x, y, r = 60, o = {}) { const { a = 1, u = 1, mis = 0, grijs = 0, t = 0, velum = 1 } = o; if (a <= 0.01) return; ctx.save(); ctx.globalAlpha *= a; ctx.translate(x, y);
  const sch = grijs > 0.5 ? '#8A8F98' : '#E4D6B0', schR = grijs > 0.5 ? '#B0B4BC' : '#C9A35C', vlees = grijs > 0.5 ? '#6A6E76' : '#C98A6A';
  // velum (trilhaarkroon) aan de bovenkant
  if (velum > 0.01 && grijs < 0.5) { ctx.save(); ctx.globalAlpha *= velum; const vy = -r * (0.55 + 0.35 * u); ctx.fillStyle = rgba('#E9B79A', 0.9); ctx.beginPath(); ctx.ellipse(0, vy, r * 0.62, r * 0.26, 0, Math.PI, 0); ctx.fill();
    ctx.strokeStyle = '#F2DCCB'; ctx.lineWidth = Math.max(1, r * 0.03); for (let i = 0; i < 15; i++) { const an = Math.PI + i / 14 * Math.PI, bx = Math.cos(an) * r * 0.62, by = vy + Math.sin(an) * r * 0.26, w = Math.sin(t * 9 + i * 0.7) * 0.25; ctx.beginPath(); ctx.moveTo(bx, by); ctx.lineTo(bx + Math.cos(an + w) * r * 0.16, by + Math.sin(an + w) * r * 0.16); ctx.stroke(); } ctx.restore(); }
  // lijf (trochofoor) of kleppen (D-larve)
  if (u < 0.99) { ctx.save(); ctx.globalAlpha *= 1 - u * 0.8; _bol(ctx, 0, 0, r * 0.55, vlees, lighten(vlees, 0.25), 1.5); ctx.restore(); }
  if (u > 0.01) { ctx.save(); const hw = r * (0.6 + 0.4 * u), slot = -r * 0.55; ctx.globalAlpha *= clamp(u * 1.4, 0, 1);
    ctx.beginPath(); ctx.moveTo(-hw, slot + (mis * r * 0.18)); ctx.quadraticCurveTo(0, slot - mis * r * 0.22, hw, slot + mis * r * 0.05);
    const onder = r * (0.2 + 0.65 * u) * (1 - mis * 0.25); ctx.bezierCurveTo(hw * 1.08, slot + onder * 1.2, hw * 0.55, slot + r * 0.55 + onder, 0, slot + r * 0.6 + onder);
    ctx.bezierCurveTo(-hw * 0.55, slot + r * 0.55 + onder, -hw * 1.08, slot + onder * 1.2, -hw, slot + (mis * r * 0.18)); ctx.closePath(); ctx.fillStyle = rgba(sch, 0.92); ctx.fill(); ctx.strokeStyle = schR; ctx.lineWidth = Math.max(1.5, r * 0.04); ctx.stroke();
    ctx.save(); ctx.clip(); ctx.fillStyle = rgba(vlees, 0.45); ctx.beginPath(); ctx.ellipse(0, slot + r * 0.55, hw * 0.55, r * 0.42, 0, 0, 6.283); ctx.fill(); // ingewanden door de dunne schelp
    ctx.strokeStyle = rgba(schR, 0.5); ctx.lineWidth = 1.2; for (let k = 1; k <= 3; k++) { ctx.beginPath(); ctx.ellipse(0, slot - r * 0.05, hw * (0.3 + k * 0.2), (r * 0.3 + onder) * (0.3 + k * 0.2) + r * 0.2, 0, 0.15, Math.PI - 0.15); ctx.stroke(); }
    if (mis > 0.3) { ctx.fillStyle = rgba('#1A2740', 0.8 * mis); ctx.beginPath(); ctx.moveTo(hw * 0.2, slot + r); ctx.lineTo(hw * 0.9, slot + r * 0.3); ctx.lineTo(hw, slot + r * 1.4); ctx.closePath(); ctx.fill(); } // gat in de schelp
    ctx.restore();
    ctx.strokeStyle = schR; ctx.lineWidth = Math.max(2, r * 0.05); ctx.beginPath(); ctx.moveTo(-hw * 0.85, slot + mis * r * 0.15); ctx.quadraticCurveTo(0, slot - mis * r * 0.2, hw * 0.85, slot + mis * r * 0.05); ctx.stroke(); // slotlijn
    ctx.restore(); }
  ctx.restore(); }

// koraal (vertakt, klein, ver weg): steenkoraal-takjes in koraalroze met kalkwit, op een stukje rif
function mb2_koraal(ctx, x, y, s = 1, o = {}) { const { a = 1, bleek = 0 } = o; if (a <= 0.01) return; ctx.save(); ctx.globalAlpha *= a; ctx.translate(x, y); ctx.scale(s, s);
  const kl = bleek > 0.5 ? '#D8D2C6' : '#D88A6E', kd = bleek > 0.5 ? '#A8A296' : '#B0644C';
  const tak = (x0, y0, an, l, d) => { if (d > 4 || l < 6) return; const x1 = x0 + Math.cos(an) * l, y1 = y0 + Math.sin(an) * l; ctx.strokeStyle = kl; ctx.lineWidth = Math.max(3, 11 - d * 2); ctx.lineCap = 'round'; ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(x1, y1); ctx.stroke();
    tak(x1, y1, an - 0.45 - hash(d * 7 + l) * 0.2, l * 0.74, d + 1); tak(x1, y1, an + 0.4 + hash(d * 3 + l) * 0.2, l * 0.7, d + 1); };
  ctx.fillStyle = '#5A6478'; ctx.beginPath(); ctx.ellipse(0, 4, 90, 16, 0, 0, 6.283); ctx.fill();
  tak(-30, 0, -1.75, 46, 0); tak(25, 0, -1.4, 52, 0); tak(-2, 0, -1.6, 38, 1);
  ctx.fillStyle = kd; for (let i = 0; i < 6; i++) { ctx.beginPath(); ctx.ellipse(-60 + i * 24, -6, 12, 8, 0, Math.PI, 0); ctx.fill(); }
  ctx.restore(); }
